// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type ResolutionDropdownProps = Record<string, any>;

const ResolutionDropdown: React.FC<ResolutionDropdownProps> = ({
  resolutions = ["144p", "240p", "720p", "1080p"],
  backgroundColor = "#ffffff",
  transparentBackground = true,
  dropdownColor = "#b0b3b5",
  textColor = "#000000",
  highlightColor = "#9da0a2",
  durationInSeconds = 8,
  animationScale = 1.0,
  actionDurationSeconds = 1.5,
  pauseDurationSeconds = 0.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;
  const s = (Math.min(width, height) / 1080) * animationScale;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Dimensions
  const dropW = 340 * s;
  const headerH = 90 * s;
  const itemH = 90 * s;
  const dropX = width / 2 - dropW / 2;
  const dropY = height / 2 - headerH / 2 - 150 * s; // offset up to make room for list
  
  // Interaction Targets
  const chevX = dropX + dropW - 50 * s;
  const chevY = dropY + headerH / 2;
  const restX = dropX + dropW + 120 * s;
  const restY = dropY + headerH / 2 + 100 * s;
  const itemCenterX = dropX + dropW / 2;

  // Animation Choreography Logic
  const totalCycles = Math.max(0, resolutions.length - 1);
  
  const actionFramesRaw = actionDurationSeconds * fps;
  const pauseFramesRaw = pauseDurationSeconds * fps;
  const cycleFramesRaw = actionFramesRaw + pauseFramesRaw;
  const totalFramesNeeded = cycleFramesRaw * totalCycles + 20;

  // Scale action and pause durations down proportionally ONLY if they exceed the duration
  let scaleFactor = 1;
  if (totalFramesNeeded > durationInFrames) {
    scaleFactor = (durationInFrames - 20) / (cycleFramesRaw * totalCycles);
  }
  const actionFrames = actionFramesRaw * scaleFactor;
  const pauseFrames = pauseFramesRaw * scaleFactor;
  const cycleFrames = actionFrames + pauseFrames;

  const cursorXInput = [0];
  const cursorXOutput = [restX];
  const cursorYInput = [0];
  const cursorYOutput = [restY];
  const cursorScaleInput = [0];
  const cursorScaleOutput = [1];
  const dropOpenInput = [0];
  const dropOpenOutput = [0];

  let currentSelectedIndex = 0;
  let hoverIndex = -1;

  let lastScaleFrame = -1;
  const addScaleClick = (f: number) => {
    if (f > lastScaleFrame + 6) {
      cursorScaleInput.push(f, f + 2, f + 5);
      cursorScaleOutput.push(1, 0.8, 1);
      lastScaleFrame = f + 5;
    }
  };

  let lastDropFrame = -1;
  const addDropState = (f: number, state: number) => {
    if (f > lastDropFrame) {
      dropOpenInput.push(f);
      dropOpenOutput.push(state);
      lastDropFrame = f;
    }
  };

  if (totalCycles > 0) {
    for (let i = 0; i < totalCycles; i++) {
      const start = 10 + i * cycleFrames;
      
      const pRest1 = start;
      const pChevMove = start + 0.20 * actionFrames;
      const pChevClick = start + 0.25 * actionFrames;
      const pOpenEnd = start + 0.35 * actionFrames;
      const pItemMove = start + 0.55 * actionFrames;
      const pItemClick = start + 0.60 * actionFrames;
      const pCloseEnd = start + 0.75 * actionFrames;
      const pRestMove = start + 0.90 * actionFrames;
      const pRest2 = start + actionFrames + pauseFrames - 0.01;

      const targetY = dropY + headerH + (i + 1) * itemH + itemH / 2;

      // Cursor movement
      cursorXInput.push(pRest1, pChevMove, pOpenEnd, pItemMove, pItemClick, pRestMove, pRest2);
      cursorXOutput.push(restX, chevX, chevX, itemCenterX, itemCenterX, restX, restX);
      cursorYInput.push(pRest1, pChevMove, pOpenEnd, pItemMove, pItemClick, pRestMove, pRest2);
      cursorYOutput.push(restY, chevY, chevY, targetY, targetY, restY, restY);

      // Clicks
      addScaleClick(pChevMove);
      addScaleClick(pItemMove);

      // Dropdown State
      addDropState(pChevClick, 0);
      addDropState(pOpenEnd, 1);
      addDropState(pItemClick, 1);
      addDropState(pCloseEnd, 0);

      // Value Updates
      if (frame >= pItemClick) {
        currentSelectedIndex = i + 1;
      }
      if (frame >= pItemMove && frame < pCloseEnd) {
        hoverIndex = i + 1;
      }
    }
  }

  // Ensure arrays close out properly
  const lastXInput = cursorXInput[cursorXInput.length - 1];
  if (durationInFrames > lastXInput) {
    cursorXInput.push(durationInFrames); cursorXOutput.push(restX);
  }
  const lastYInput = cursorYInput[cursorYInput.length - 1];
  if (durationInFrames > lastYInput) {
    cursorYInput.push(durationInFrames); cursorYOutput.push(restY);
  }
  const lastScaleInputVal = cursorScaleInput[cursorScaleInput.length - 1];
  if (durationInFrames > lastScaleInputVal) {
    cursorScaleInput.push(durationInFrames); cursorScaleOutput.push(1);
  }
  const lastDropInputVal = dropOpenInput[dropOpenInput.length - 1];
  if (durationInFrames > lastDropInputVal) {
    dropOpenInput.push(durationInFrames); dropOpenOutput.push(0);
  }

  // Apply Interpolations
  const cx = interpolate(frame, cursorXInput, cursorXOutput, { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.quad) });
  const cy = interpolate(frame, cursorYInput, cursorYOutput, { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.quad) });
  const cScale = interpolate(frame, cursorScaleInput, cursorScaleOutput, { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const dropProgress = interpolate(frame, dropOpenInput, dropOpenOutput, { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.ease) });

  const activeText = resolutions[currentSelectedIndex] || "";
  const listHeight = dropProgress * (resolutions.length * itemH);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Dropdown Container */}
      <div style={{
        position: 'absolute',
        top: dropY,
        left: dropX,
        width: dropW,
        zIndex: 10,
        transition: 'none'
      }}>
        
        {/* Header */}
        <div style={{
          height: headerH,
          backgroundColor: dropdownColor,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: `0 ${30 * s}px`,
          borderBottom: `${2 * s}px solid rgba(0,0,0,0.15)`,
          borderTopLeftRadius: 10 * s,
          borderTopRightRadius: 10 * s,
          borderBottomLeftRadius: dropProgress > 0.1 ? 0 : 10 * s,
          borderBottomRightRadius: dropProgress > 0.1 ? 0 : 10 * s,
          boxShadow: dropProgress < 0.1 ? `0px ${4 * s}px ${10 * s}px rgba(0,0,0,0.1)` : 'none',
          transition: 'none'
        }}>
          <span style={{
            color: textColor,
            fontSize: 50 * s,
            fontWeight: 500,
            letterSpacing: `-0.02em`
          }}>
            {activeText}
          </span>
          
          {/* Chevron */}
          <svg width={30 * s} height={30 * s} viewBox="0 0 24 24" style={{
            transform: `rotate(${dropProgress * 180}deg)`,
            transition: 'none'
          }}>
            <path 
              d="M 4 8 L 12 16 L 20 8" 
              fill="none" 
              stroke={textColor} 
              strokeWidth={3} 
              strokeLinecap="round" 
              strokeLinejoin="round" 
            />
          </svg>
        </div>

        {/* List Container */}
        <div style={{
          width: '100%',
          height: listHeight,
          backgroundColor: dropdownColor,
          overflow: 'hidden',
          borderBottomLeftRadius: 10 * s,
          borderBottomRightRadius: 10 * s,
          boxShadow: `0px ${15 * s}px ${30 * s}px rgba(0,0,0,${0.2 * dropProgress})`,
          transition: 'none',
          display: 'flex',
          flexDirection: 'column'
        }}>
          {resolutions.map((res, index) => {
            const isHovered = hoverIndex === index;
            return (
              <div key={index} style={{
                height: itemH,
                width: '100%',
                display: 'flex',
                alignItems: 'center',
                padding: `0 ${30 * s}px`,
                backgroundColor: isHovered ? highlightColor : 'transparent',
                boxSizing: 'border-box',
                transition: 'none'
              }}>
                <span style={{
                  color: textColor,
                  fontSize: 50 * s,
                  fontWeight: 500,
                  letterSpacing: `-0.02em`
                }}>
                  {res}
                </span>
              </div>
            );
          })}
        </div>

      </div>

      {/* Cursor */}
      <div style={{
        position: 'absolute',
        left: cx,
        top: cy,
        transform: `scale(${cScale})`,
        transformOrigin: '0 0',
        transition: 'none',
        zIndex: 100,
      }}>
        <svg 
          width={50 * s} 
          height={50 * s} 
          viewBox="0 0 32 32" 
          style={{ 
            filter: `drop-shadow(0px ${4 * s}px ${6 * s}px rgba(0,0,0,0.3))` 
          }}
        >
          <path 
            d="M 0 0 L 0 20 L 5 16 L 9 24 L 12 22 L 8 14 L 16 14 Z" 
            fill="white" 
            stroke="black" 
            strokeWidth={1.5} 
            strokeLinejoin="round" 
          />
        </svg>
      </div>

    </AbsoluteFill>
  );
};

export default ResolutionDropdown;